24	/**
25	 * Per-process counters used by the request-isolation suites. The aggregation
26	 * state itself is per-request; these counters only let tests observe how many
27	 * pipes/handlers ran for a sequence of requests. They are reset in every test's
28	 * beforeEach via {@link resetIsolationState}.
29	 */
30	export const isolationState: {
31	  pipeCalls: string[];
32	  handlerCalls: Record<string, number>;
33	} = {
34	  pipeCalls: [],
35	  handlerCalls: {},
36	};
37	
38	export function resetIsolationState(): void {
39	  isolationState.pipeCalls = [];
40	  isolationState.handlerCalls = {};
41	  MyParamFilter.received = [];
42	  MyWideFilter.last = null;
43	}
