50	class NumberPipe implements PipeTransform<string, number> {
51	  constructor(private readonly errorMessage: string) {}
52	
53	  transform(value: string): number {
54	    isolationState.pipeCalls.push(this.errorMessage);
55	    const parsed = Number(value);
56	    if (Number.isNaN(parsed) || value.trim() === '') {
57	      throw new BadRequestException(this.errorMessage);
58	    }
59	    return parsed;
60	  }
61	}
62	
63	class SlowNumberPipe implements PipeTransform<
64	  string,
65	  Promise<number> | number
66	> {
67	  constructor(
68	    private readonly errorMessage: string,
69	    private readonly delayMs: number,
70	  ) {}
71	
72	  async transform(value: string): Promise<number> {
73	    isolationState.pipeCalls.push(this.errorMessage);
74	    await new Promise(resolve => setTimeout(resolve, this.delayMs));
75	    const parsed = Number(value);
76	    if (Number.isNaN(parsed) || value.trim() === '') {
77	      throw new BadRequestException(this.errorMessage);
78	    }
79	    return parsed;
80	  }
81	}
82	
83	// The limit chain runs after a DefaultValuePipe, so its input is either the
84	// raw query string or the seeded default number. Explicit invalid values must
85	// fail the chain (LIMIT) instead of silently falling back to the default.
86	class LimitPipe implements PipeTransform<string | number, number> {
87	  transform(value: string | number): number {
88	    isolationState.pipeCalls.push('LIMIT');
89	    if (typeof value === 'string' && value.trim() === '') {
90	      throw new BadRequestException('LIMIT');
91	    }
92	    const parsed = Number(value);
93	    if (Number.isNaN(parsed)) {
94	      throw new BadRequestException('LIMIT');
95	    }
96	    return parsed;
97	  }
98	}
99	
100	class SlowLimitPipe implements PipeTransform<
101	  string | number,
102	  Promise<number> | number
103	> {
104	  constructor(private readonly delayMs: number) {}
105	
106	  async transform(value: string | number): Promise<number> {
107	    isolationState.pipeCalls.push('LIMIT');
108	    await new Promise(resolve => setTimeout(resolve, this.delayMs));
109	    if (typeof value === 'string' && value.trim() === '') {
110	      throw new BadRequestException('LIMIT');
111	    }
112	    const parsed = Number(value);
113	    if (Number.isNaN(parsed)) {
114	      throw new BadRequestException('LIMIT');
115	    }
116	    return parsed;
117	  }
118	}
119	
120	// `currency` is a required query parameter: a missing or blank value is a
121	// request error (CURRENCY), never masked by the optional `limit` default.
122	class CurrencyPipe implements PipeTransform<string | undefined, string> {
123	  transform(value: string | undefined): string {
124	    isolationState.pipeCalls.push('CURRENCY');
125	    if (value === undefined || value.trim() === '') {
126	      throw new BadRequestException('CURRENCY');
127	    }
128	    return value.toUpperCase();
129	  }
130	}
131	
132	class NotFoundPipe implements PipeTransform<string, string> {
133	  transform(value: string): string {
134	    isolationState.pipeCalls.push('N');
135	    if (value === 'missing') {
136	      throw new NotFoundException('NOT-FOUND');
137	    }
138	    return value;
139	  }
140	}
141	
142	class PartialAbortPipe implements PipeTransform<string, string> {
143	  transform(value: string): string {
144	    isolationState.pipeCalls.push('M');
145	    if (value === 'abort') {
146	      // A non-BadRequest HttpException: aggregation must abort immediately and
147	      // the default exception layer keeps its regular status/body path.
148	      throw new ForbiddenException('ABORTED');
149	    }
150	    return value;
151	  }
152	}
153	
154	class BodyPipe implements PipeTransform<any, any> {
155	  transform(body: any): any {
156	    isolationState.pipeCalls.push('BODY');
157	    if (!body || body.valid !== true) {
158	      throw new BadRequestException('BODY');
159	    }
160	    return { ...body, transformed: true };
161	  }
162	}
163	
164	class CustomUserPipe implements PipeTransform<any, any> {
165	  transform(user: any): any {
166	    isolationState.pipeCalls.push('CUSTOM');
167	    if (!user || user.ok !== true) {
168	      throw new BadRequestException('CUSTOM');
169	    }
170	    return user;
171	  }
172	}
173	
174	class HeaderNumberPipe implements PipeTransform<string | undefined, number> {
175	  transform(value: string | undefined): number {
176	    isolationState.pipeCalls.push('H');
177	    const parsed = Number(value);
178	    if (
179	      value === undefined ||
180	      String(value).trim() === '' ||
181	      Number.isNaN(parsed)
182	    ) {
183	      throw new BadRequestException('H');
184	    }
185	    return parsed;
186	  }
187	}
188	
189	class HeaderAbortPipe implements PipeTransform<string | undefined, string> {
190	  transform(value: string | undefined): string {
191	    isolationState.pipeCalls.push('HF');
192	    if (value === 'abort') {
193	      // A non-BadRequest exception raised by a header pipe: aggregation must
194	      // abort immediately and the staged param/query messages are discarded.
195	      throw new ForbiddenException('HEADER-ABORT');
196	    }
197	    return value ?? '';
198	  }
199	}
200	
201	const User = createParamDecorator((_data: unknown, ctx: ExecutionContext) => {
202	  const request = ctx.switchToHttp().getRequest();
203	  const name = request.headers['x-user'];
204	  return name ? { name, ok: true } : { ok: false };
205	});
