207	@Catch(BadRequestException)
208	export class MyParamFilter implements ExceptionFilter {
209	  public static received: Array<{
210	    status: number;
211	    message: unknown;
212	  }> = [];
213	
214	  constructor(private readonly adapterHost: HttpAdapterHost) {}
215	
216	  catch(exception: BadRequestException, host: ArgumentsHost) {
217	    const { httpAdapter } = this.adapterHost;
218	    const response = host.switchToHttp().getResponse();
219	    const responseBody = exception.getResponse() as { message: unknown };
220	    // Record every invocation so tests can assert the filter sees the
221	    // aggregated exception exactly once (never per-parameter exceptions).
222	    MyParamFilter.received.push({
223	      status: exception.getStatus(),
224	      message: responseBody.message,
225	    });
226	    const count = Array.isArray(responseBody.message)
227	      ? responseBody.message.length
228	      : 1;
229	    httpAdapter.reply(response, { code: 'PARAMS_INVALID', count }, 422);
230	  }
231	}
232	
233	@Catch()
234	export class MyWideFilter implements ExceptionFilter {
235	  public static last: { name: string; status?: number } | null = null;
236	
237	  constructor(private readonly adapterHost: HttpAdapterHost) {}
238	
239	  catch(exception: unknown, host: ArgumentsHost) {
240	    const { httpAdapter } = this.adapterHost;
241	    const response = host.switchToHttp().getResponse();
242	    MyWideFilter.last = {
243	      name: (exception as Error)?.name,
244	      status:
245	        typeof (exception as { getStatus?: () => number })?.getStatus ===
246	        'function'
247	          ? (exception as { getStatus: () => number }).getStatus()
248	          : undefined,
249	    };
250	    httpAdapter.reply(response, { code: 'WIDE' }, 418);
251	  }
252	}
