254	@Controller('p')
255	export class AggregateParamErrorsController {
256	  @AggregateParamErrors()
257	  @Get(':id')
258	  public aggregated(
259	    @Param('id', new NumberPipe('A')) id: number,
260	    @Query('limit', new NumberPipe('B')) limit: number,
261	  ) {
262	    recordHandler('aggregated');
263	    return `${id},${limit}`;
264	  }
265	
266	  @Get('legacy/:id')
267	  public legacy(
268	    @Param('id', new NumberPipe('A')) id: number,
269	    @Query('limit', new NumberPipe('B')) limit: number,
270	  ) {
271	    recordHandler('legacy');
272	    return `${id},${limit}`;
273	  }
274	
275	  @AggregateParamErrors()
276	  @UseFilters(MyParamFilter)
277	  @Get('filtered/:id')
278	  public filtered(
279	    @Param('id', new NumberPipe('A')) id: number,
280	    @Query('limit', new NumberPipe('B')) limit: number,
281	  ) {
282	    recordHandler('filtered');
283	    return `${id},${limit}`;
284	  }
285	
286	  @AggregateParamErrors()
287	  @Get('other/:id')
288	  public other(
289	    @Param('id', new NotFoundPipe()) id: string,
290	    @Query('limit', new NumberPipe('B')) limit: number,
291	  ) {
292	    recordHandler('other');
293	    return `${id},${limit}`;
294	  }
295	
296	  // The first @Param() fails with a BadRequest (collected), the second
297	  // @Param() aborts with a non-BadRequest error: the partially collected
298	  // message must die with this request.
299	  @AggregateParamErrors()
300	  @Get('partial/:id/:mode')
301	  public partial(
302	    @Param('id', new NumberPipe('A')) id: number,
303	    @Param('mode', new PartialAbortPipe()) mode: string,
304	    @Query('limit', new NumberPipe('B')) limit: number,
305	  ) {
306	    recordHandler('partial');
307	    return `${id},${mode},${limit}`;
308	  }
309	
310	  // Delayed param pipe used to keep a valid and an invalid request genuinely
311	  // in flight at the same time in the parallel tests.
312	  @AggregateParamErrors()
313	  @Get('slow/:id')
314	  public slow(
315	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
316	    @Query('limit', new NumberPipe('B')) limit: number,
317	  ) {
318	    recordHandler('slow');
319	    return `${id},${limit}`;
320	  }
321	
322	  // @Body() must stay outside the aggregation scope: its pipe error aborts
323	  // immediately even when a @Param() failed first.
324	  @AggregateParamErrors()
325	  @Post('body/:id')
326	  public withBody(
327	    @Param('id', new NumberPipe('A')) id: number,
328	    @Body(new BodyPipe()) body: { transformed: boolean },
329	    @Query('limit', new NumberPipe('B')) limit: number,
330	  ) {
331	    recordHandler('body');
332	    return `${id},${limit},${body.transformed ? 'transformed' : 'raw'}`;
333	  }
334	
335	  // Custom parameter extractors must keep the existing (fail-fast) scope.
336	  @AggregateParamErrors()
337	  @Get('custom/:id')
338	  public withCustom(
339	    @Param('id', new NumberPipe('A')) id: number,
340	    @User(new CustomUserPipe()) user: { name: string },
341	    @Query('limit', new NumberPipe('B')) limit: number,
342	  ) {
343	    recordHandler('custom');
344	    return `${id},${limit},${user.name}`;
345	  }
346	
347	  // @Headers() parameters are an independent input domain: the header pipe
348	  // always runs and its transformed value reaches the handler, but a header
349	  // failure aborts the resolution immediately and discards any @Param()/
350	  // @Query() messages collected so far.
351	  @AggregateParamErrors()
352	  @Get('headers/:id')
353	  public withHeaders(
354	    @Param('id', new NumberPipe('A')) id: number,
355	    @Headers('x-token', new HeaderNumberPipe()) token: number,
356	    @Query('limit', new NumberPipe('B')) limit: number,
357	  ) {
358	    recordHandler('headers');
359	    return `${id},${token},${limit}`;
360	  }
361	
362	  // The filter must observe only the header exception when the header pipe
363	  // fails - never the staged @Param()/@Query() messages.
364	  @AggregateParamErrors()
365	  @UseFilters(MyParamFilter)
366	  @Get('headers-filtered/:id')
367	  public withHeadersFiltered(
368	    @Param('id', new NumberPipe('A')) id: number,
369	    @Headers('x-token', new HeaderNumberPipe()) token: number,
370	    @Query('limit', new NumberPipe('B')) limit: number,
371	  ) {
372	    recordHandler('headersFiltered');
373	    return `${id},${token},${limit}`;
374	  }
375	
376	  // A non-BadRequest header exception propagates unchanged through the
377	  // catch-all filter; the staged param/query messages die with the request.
378	  @AggregateParamErrors()
379	  @UseFilters(MyWideFilter)
380	  @Get('headers-wide/:id')
381	  public withHeadersWide(
382	    @Param('id', new NumberPipe('A')) id: number,
383	    @Headers('x-mode', new HeaderAbortPipe()) mode: string,
384	    @Query('limit', new NumberPipe('B')) limit: number,
385	  ) {
386	    recordHandler('headersWide');
387	    return `${id},${mode},${limit}`;
388	  }
389	
390	  // Unannotated route with a header pipe: the header pipe runs, but the
391	  // fail-fast compatibility path is unchanged.
392	  @Get('headers-legacy/:id')
393	  public withHeadersLegacy(
394	    @Param('id', new NumberPipe('A')) id: number,
395	    @Headers('x-token', new HeaderNumberPipe()) token: number,
396	    @Query('limit', new NumberPipe('B')) limit: number,
397	  ) {
398	    recordHandler('headersLegacy');
399	    return `${id},${token},${limit}`;
400	  }
401	
402	  // Delayed pipes on all three domains, used to keep mixed-failure requests
403	  // genuinely in flight at the same time in the parallel tests.
404	  @AggregateParamErrors()
405	  @Get('headers-slow/:id')
406	  public withHeadersSlow(
407	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
408	    @Headers('x-token', new SlowNumberPipe('H', 30)) token: number,
409	    @Query('limit', new SlowNumberPipe('B', 30)) limit: number,
410	  ) {
411	    recordHandler('headersSlow');
412	    return `${id},${token},${limit}`;
413	  }
414	
415	  // A catch-all method filter must receive the original non-request exception
416	  // unchanged (not the aggregated BadRequest).
417	  @AggregateParamErrors()
418	  @UseFilters(MyWideFilter)
419	  @Get('wide/:id')
420	  public wide(
421	    @Param('id', new NotFoundPipe()) id: string,
422	    @Query('limit', new NumberPipe('B')) limit: number,
423	  ) {
424	    recordHandler('wide');
425	    return `${id},${limit}`;
426	  }
427	
428	  // Optional query value with a per-resolution default: when `limit` is
429	  // absent, DefaultValuePipe seeds 10 which still runs through the same
430	  // LimitPipe conversion as an explicit value. An explicit invalid value
431	  // must fail (LIMIT), never fall back to 10. `currency` is required.
432	  @AggregateParamErrors()
433	  @Get('defaults/:id')
434	  public defaults(
435	    @Param('id', new NumberPipe('A')) id: number,
436	    @Query('currency', new CurrencyPipe()) currency: string,
437	    @Query('limit', new DefaultValuePipe(10), new LimitPipe())
438	    limit: number,
439	  ) {
440	    recordHandler('defaults');
441	    return { id, currency, limit };
442	  }
443	
444	  // Delayed variant of the defaults route used to keep a default-success and
445	  // an explicit-invalid request genuinely in flight in the parallel tests.
446	  @AggregateParamErrors()
447	  @Get('defaults-slow/:id')
448	  public defaultsSlow(
449	    @Param('id', new SlowNumberPipe('A', 30)) id: number,
450	    @Query('currency', new CurrencyPipe()) currency: string,
451	    @Query('limit', new DefaultValuePipe(10), new SlowLimitPipe(30))
452	    limit: number,
453	  ) {
454	    recordHandler('defaultsSlow');
455	    return { id, currency, limit };
456	  }
457	}
