1	import { INestApplication } from '@nestjs/common';
2	import { Test } from '@nestjs/testing';
3	import request from 'supertest';
4	import { MyParamFilter } from '../src/aggregate-param-errors.controller.js';
5	import { AggregateParamErrorsModule } from '../src/aggregate-param-errors.module.js';
6	
7	describe('AggregateParamErrors (Express)', () => {
8	  let server: any;
9	  let app: INestApplication;
10	
11	  beforeEach(async () => {
12	    const moduleRef = await Test.createTestingModule({
13	      imports: [AggregateParamErrorsModule],
14	    }).compile();
15	
16	    app = moduleRef.createNestApplication();
17	    server = app.getHttpServer();
18	    MyParamFilter.received = [];
19	    await app.init();
20	  });
21	
22	  afterEach(async () => {
23	    await app.close();
24	  });
25	
26	  describe('when every parameter is valid', () => {
27	    it('runs the handler with the transformed parameters', () => {
28	      return request(server).get('/p/7?limit=10').expect(200, '7,10');
29	    });
30	  });
31	
32	  describe('when a single @Param/@Query pipe fails', () => {
33	    it('responds with the aggregated 400 body (single-element message)', () => {
34	      return request(server)
35	        .get('/p/7?limit=x')
36	        .expect(400)
37	        .expect({
38	          statusCode: 400,
39	          error: 'Bad Request',
40	          message: ['B'],
41	        });
42	    });
43	  });
44	
45	  describe('when multiple @Param/@Query pipes fail', () => {
46	    it('skips the handler and responds with one 400 containing all messages in parameter order', () => {
47	      return request(server)
48	        .get('/p/abc?limit=x')
49	        .expect(400)
50	        .expect({
51	          statusCode: 400,
52	          error: 'Bad Request',
53	          message: ['A', 'B'],
54	        });
55	    });
56	  });
57	
58	  describe('when a custom exception filter is applied', () => {
59	    it('the filter receives only the aggregated exception once and rewrites the response', async () => {
60	      const response = await request(server)
61	        .get('/p/filtered/abc?limit=x')
62	        .expect(422);
63	
64	      expect(response.body).toEqual({
65	        code: 'PARAMS_INVALID',
66	        count: 2,
67	      });
68	      expect(MyParamFilter.received).toHaveLength(1);
69	      expect(MyParamFilter.received[0]).toEqual({
70	        status: 400,
71	        message: ['A', 'B'],
72	      });
73	    });
74	
75	    it('reports the count of a single error consistently', () => {
76	      return request(server)
77	        .get('/p/filtered/7?limit=x')
78	        .expect(422)
79	        .expect({ code: 'PARAMS_INVALID', count: 1 });
80	    });
81	  });
82	
83	  describe('when the handler is not annotated with @AggregateParamErrors', () => {
84	    it('keeps the existing fail-fast path (string message, first failure)', () => {
85	      return request(server).get('/p/legacy/7?limit=x').expect(400).expect({
86	        statusCode: 400,
87	        error: 'Bad Request',
88	        message: 'B',
89	      });
90	    });
91	  });
92	
93	  describe('when a @Param/@Query pipe throws a non-BadRequest exception', () => {
94	    it('propagates the original exception unchanged (existing path)', () => {
95	      return request(server)
96	        .get('/p/other/missing?limit=x')
97	        .expect(404)
98	        .expect({
99	          statusCode: 404,
100	          error: 'Not Found',
101	          message: 'NOT-FOUND',
102	        });
103	    });
104	  });
105	
106	  describe('when a @Headers() parameter is present', () => {
107	    it('runs the header pipe and hands all transformed values to the handler', () => {
108	      return request(server)
109	        .get('/p/headers/7?limit=10')
110	        .set('x-token', '5')
111	        .expect(200, '7,5,10');
112	    });
113	
114	    it('responds with only the aggregated messages when the header is valid', () => {
115	      return request(server)
